		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 497, "\">\n\t\t// The vanilla pendant of notification-settings.tsx's checked record:\n\t\t// the select-all checkbox drives the items, the items drive the\n\t\t// select-all state including Base UI's indeterminate attributes\n\t\t// (aria-checked=\"mixed\" + data-indeterminate), which the checkbox\n\t\t// component itself does not model.\n\t\t(() => {\n\t\t\tif (window.__templDemoNotificationSettings) return;\n\t\t\twindow.__templDemoNotificationSettings = true;\n\t\t\tconst partsOf = (card) => {\n\t\t\t\tconst all = card.querySelector(\"#notify-all\");\n\t\t\t\tconst items = [...card.querySelectorAll(\"[data-slot=checkbox] + input\")].filter((i) => i !== all);\n\t\t\t\treturn { all, items };\n\t\t\t};\n\t\t\tconst setChecked = (input, checked) => {\n\t\t\t\tif (input.checked === checked) return;\n\t\t\t\tinput.checked = checked;\n\t\t\t\tinput.dispatchEvent(new Event(\"change\", { bubbles: true }));\n\t\t\t};\n\t\t\tconst syncAll = (card) => {\n\t\t\t\tconst { all, items } = partsOf(card);\n\t\t\t\tconst allChecked = items.every((i) => i.checked);\n\t\t\t\tconst someChecked = items.some((i) => i.checked) && !allChecked;\n\t\t\t\tsetChecked(all, allChecked);\n\t\t\t\tall.indeterminate = someChecked;\n\t\t\t\tconst root = all.previousElementSibling;\n\t\t\t\troot.setAttribute(\"aria-checked\", someChecked ? \"mixed\" : String(allChecked));\n\t\t\t\troot.toggleAttribute(\"data-indeterminate\", someChecked);\n\t\t\t\tconst indicator = root.querySelector('[data-slot=\"checkbox-indicator\"]');\n\t\t\t\tindicator.toggleAttribute(\"data-indeterminate\", someChecked);\n\t\t\t\t// Base UI renders the indicator when checked or indeterminate.\n\t\t\t\tindicator.hidden = !(allChecked || someChecked);\n\t\t\t};\n\t\t\tlet updating = false;\n\t\t\tdocument.addEventListener(\"change\", (e) => {\n\t\t\t\tif (updating || !e.target.matches || !e.target.matches(\"[data-slot=checkbox] + input\")) return;\n\t\t\t\tconst card = e.target.closest(\"[data-notification-settings]\");\n\t\t\t\tif (!card) return;\n\t\t\t\tconst { all } = partsOf(card);\n\t\t\t\tconst target = e.target;\n\t\t\t\tupdating = true;\n\t\t\t\t// checkbox.js's own change listener runs after this one and\n\t\t\t\t// resets the root attributes from input.checked; the microtask\n\t\t\t\t// re-applies the derived select-all state afterwards.\n\t\t\t\tqueueMicrotask(() => {\n\t\t\t\t\tif (target === all) {\n\t\t\t\t\t\tpartsOf(card).items.forEach((i) => setChecked(i, all.checked));\n\t\t\t\t\t}\n\t\t\t\t\tsyncAll(card);\n\t\t\t\t\tupdating = false;\n\t\t\t\t});\n\t\t\t});\n\t\t\t// Initial render: two of four are checked, so the select-all\n\t\t\t// starts indeterminate, like the source's initial state. Runs\n\t\t\t// after checkbox.js's DOMContentLoaded setup pass.\n\t\t\tconst initial = () => {\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tupdating = true;\n\t\t\t\t\tdocument.querySelectorAll(\"[data-notification-settings]\").forEach(syncAll);\n\t\t\t\t\tupdating = false;\n\t\t\t\t}, 0);\n\t\t\t};\n\t\t\tif (document.readyState === \"loading\") {\n\t\t\t\tdocument.addEventListener(\"DOMContentLoaded\", initial);\n\t\t\t} else {\n\t\t\t\tinitial();\n\t\t\t}\n\t\t})();\n\t</script>")
